<template>
  <div class="page-stack">
    <section class="hero compact"><div><span class="eyebrow">HISTORICAL SESSION METRICS</span><h1>历史会话指标计算</h1><p>选择 LiteLLM 普通会话，由 Judge 根据第一条用户 Prompt 分类，并计算工具、脚本、Skill、错误、重试和伪造输出指标。</p></div></section>
    <el-alert v-if="health.store?.status!=='ok'" type="warning" :closable="false" show-icon title="MongoDB 指标接口尚未就绪" :description="health.store?.detail||'请检查 Java 查询/插入接口及 MongoDB 连接。'"/>
    <el-card shadow="never" class="panel"><el-form label-position="top" @submit.prevent="search"><div class="filters"><el-form-item label="时间范围" class="time-filter"><div class="time-filter-controls"><el-radio-group v-model="timePreset"><el-radio-button value="1d">最近 1 天</el-radio-button><el-radio-button value="7d">最近 1 周</el-radio-button><el-radio-button value="30d">最近 1 个月</el-radio-button><el-radio-button value="all">不限时间</el-radio-button><el-radio-button value="custom">自定义</el-radio-button></el-radio-group><el-date-picker v-if="timePreset==='custom'" v-model="customTimeRange" type="datetimerange" range-separator="至" start-placeholder="开始时间" end-placeholder="结束时间" :clearable="false"/></div></el-form-item><el-form-item label="End User"><el-input v-model="endUser" clearable/></el-form-item><el-form-item label="Session ID"><el-input v-model="sessionId" clearable/></el-form-item><el-form-item label="指标状态"><el-select v-model="metricStatusFilter"><el-option label="全部会话" value="all"/><el-option label="已计算指标" value="calculated"/><el-option label="未计算指标" value="uncalculated"/></el-select></el-form-item><el-form-item label="模型"><el-input v-model="model" clearable/></el-form-item><el-form-item label="查询"><el-button type="primary" native-type="submit" :loading="loading">搜索</el-button></el-form-item></div></el-form><div class="actions"><el-button type="primary" :disabled="!selected.length||health.store?.status!=='ok'" :loading="submitting" @click="calculateSelected">开始计算所选 {{selected.length}} 个会话</el-button><el-switch v-model="useJudge" active-text="使用 LLM Judge"/><span>页面不会自动读取数据库；设置条件并点击“搜索”后才会查询。</span></div></el-card>
    <el-card v-if="visibleJob" id="metric-process-panel" shadow="never" class="panel job-panel">
      <template #header><div class="job-title"><div><b>{{processJob?'已保存的计算过程':'指标计算过程'}}</b><code>{{visibleJob.job_id}}</code></div><div class="job-title-actions"><el-button v-if="processJob" link type="primary" @click="processJob=null">{{job?'返回当前任务':'关闭过程'}}</el-button><el-tag :type="visibleJob.status==='completed'?'success':visibleJob.failed?'danger':'warning'">{{jobStatus(visibleJob.status)}}</el-tag></div></div></template>
      <el-progress :percentage="processJob?100:jobProgress" :status="visibleJob.failed?'exception':visibleJob.status==='completed'?'success':undefined"/>
      <div class="job-summary"><span>阶段：<b>{{jobPhase(visibleJob.phase)}}</b></span><span>进度：<b>{{visibleJob.completed||0}} / {{visibleJob.total||0}}</b></span><span v-if="visibleJob.current_session_id">当前会话：<code>{{visibleJob.current_session_id}}</code></span><span v-if="processJob">过程记录：<code>{{processJob.mongo_record_id||'MongoDB'}}</code></span></div>
      <div class="session-pipelines">
        <section v-for="pipeline in sessionPipelines" :key="pipeline.sessionId" class="session-pipeline">
          <header><div><b>会话指标流水线</b><code>{{pipeline.sessionId}}</code></div><el-tag :type="pipelineTag(pipeline.status)">{{pipelineStatus(pipeline.status)}}</el-tag></header>
          <div class="pipeline-steps">
            <article v-for="(step,index) in pipeline.steps" :key="step.key" :class="`is-${step.status}`">
              <div class="step-index">{{index+1}}</div>
              <div class="step-main"><b>{{step.label}}</b><span>{{step.description}}</span><small v-if="step.latest">{{step.latest.message}} · {{formatTime(step.latest.timestamp)}}</small><strong v-if="step.judgeTiming" class="judge-timer" :class="{'is-live':step.judgeTiming.running}"><i v-if="step.judgeTiming.running"/>{{step.judgeTiming.label}} {{step.judgeTiming.duration}}</strong></div>
              <el-tag size="small" :type="stepTag(step.status)">{{stepStatus(step.status)}}</el-tag>
              <div v-if="stepFacts(step).length" class="step-facts"><div v-for="fact in stepFacts(step)" :key="fact.label"><span>{{fact.label}}</span><pre>{{formatStepValue(fact.value)}}</pre></div></div>
              <details v-if="step.events.length" class="step-result"><summary>查看全部原始事件 JSON</summary><pre>{{JSON.stringify(step.events.map(eventPayload),null,2)}}</pre></details>
            </article>
          </div>
        </section>
      </div>
      <details class="raw-events"><summary>查看完整过程事件（{{(visibleJob.events||[]).length}} 条）</summary><div class="metric-events"><article v-for="event in visibleJob.events||[]" :key="event.sequence" :class="event.stage"><i/><div><b>{{event.message}}</b><span>{{eventDetail(event)}}</span><details v-if="event.interface||event.input||event.output" class="interface-detail"><summary>查看结构化详情</summary><pre>{{JSON.stringify(eventPayload(event),null,2)}}</pre></details></div><time>{{formatTime(event.timestamp)}}</time></article><el-empty v-if="!(visibleJob.events||[]).length" description="没有已保存的过程事件" :image-size="44"/></div></details>
    </el-card>
    <el-card shadow="never" class="panel"><el-table :data="rows" row-key="root_session_id" v-loading="loading" row-class-name="metric-row" @selection-change="selected=$event" @row-click="openMetrics">
      <el-table-column label="累计质量指标" min-width="240"><template #default="{row}"><span v-if="Object.keys(row.quality_rates||{}).length">{{qualityListText(row.quality_rates)}}</span><span v-else>—</span></template></el-table-column>
      <el-table-column type="selection" width="48"/><el-table-column label="开始时间" width="175"><template #default="{row}">{{formatTime(row.started_at)}}</template></el-table-column><el-table-column label="Session ID" min-width="245" show-overflow-tooltip prop="root_session_id"/><el-table-column label="任务分类" min-width="175" show-overflow-tooltip><template #default="{row}">{{taskType(row.task_type)}}</template></el-table-column><el-table-column label="Agent" width="105"><template #default="{row}">{{row.agent||'未记录'}}</template></el-table-column><el-table-column label="模型" min-width="165" show-overflow-tooltip><template #default="{row}">{{row.models?.join('、')||'未记录'}}</template></el-table-column><el-table-column label="用户" width="125"><template #default="{row}">{{row.end_user||row.user_id||'未记录'}}</template></el-table-column><el-table-column label="交互" width="70" align="right" prop="interaction_count"/><el-table-column label="Token" width="95" align="right"><template #default="{row}">{{number(row.total_tokens)}}</template></el-table-column><el-table-column label="指标状态" width="125"><template #default="{row}"><el-tag :type="metricTag(row.metric_status)">{{metricStatus(row.metric_status)}}</el-tag></template></el-table-column><el-table-column label="操作" width="260" fixed="right"><template #default="{row}"><el-button link type="primary" @click.stop="openMetrics(row)">查看指标</el-button><el-button link type="primary" :loading="processLoading===row.root_session_id" @click.stop="showProcess(row)">查看过程</el-button><el-button link type="success" :loading="calculatingSession===row.root_session_id" @click.stop="calculateRows([row])">开始计算</el-button></template></el-table-column>
      <template #empty><el-empty :description="hasSearched?'没有符合条件的历史会话':'请选择时间范围或填写筛选条件，然后点击搜索'" :image-size="72"/></template>
    </el-table><el-pagination v-if="hasSearched&&total" v-model:current-page="page" v-model:page-size="pageSize" background layout="total, sizes, prev, pager, next" :page-sizes="[20,50,100]" :total="total" class="pagination" @current-change="load" @size-change="changeSize"/></el-card>

    <el-dialog v-model="detailVisible" width="860px" top="6vh" destroy-on-close append-to-body><template #header><div class="dialog-title"><div><span class="eyebrow">SESSION METRICS</span><b>会话指标</b><small>{{detailSession?.root_session_id}}</small></div><el-tag v-if="metricDetail" :type="metricTag(metricDetail.status)">{{metricStatus(metricDetail.status)}}</el-tag></div></template><div v-loading="detailLoading" class="metric-detail">
      <section v-if="metricDetail?.quality_summary" class="quality-summary"><h3>本会话累计质量指标</h3><p>按相同 Session ID 汇总四类原始检查记录；无记录或无法核验的指标显示为“—”。</p><div class="metric-grid rationality-grid"><article v-for="item in qualityMetricCards" :key="item.key"><span>{{item.label}}</span><b>{{formatQualityRate(item.value)}}</b><small>{{item.source}} · {{item.recordCount}} 条记录</small></article></div><details><summary>查看四类检查的逐条提取结果与汇总 JSON</summary><pre>{{JSON.stringify(metricDetail.quality_summary,null,2)}}</pre></details></section>
      <template v-if="metricDetail"><div class="detail-summary"><div><span>任务类型</span><b>{{taskType(metricDetail.task_type)}}</b></div><div><span>Agent</span><b>{{metricDetail.agent||'未记录'}}</b></div><div><span>模型</span><b>{{metricDetail.model||'未记录'}}</b></div><div><span>计算时间</span><b>{{formatTime(metricDetail.calculated_at)}}</b></div></div><div class="metric-grid"><article v-for="item in metricCards" :key="item.key"><span>{{item.label}}</span><b>{{item.value}}</b><small>{{item.help}}</small></article></div><el-divider content-position="left">Judge 与证据</el-divider><el-descriptions :column="2" border><el-descriptions-item label="分类 Judge">{{metricDetail.task_classification?.status||'未启用'}}</el-descriptions-item><el-descriptions-item label="分类理由">{{metricDetail.task_classification?.reason||metricDetail.task_classification?.error||'—'}}</el-descriptions-item><el-descriptions-item label="指标 Judge">{{metricDetail.judge?.status||'未启用'}}</el-descriptions-item><el-descriptions-item label="指标版本">{{metricDetail.metric_definition_version||'—'}}</el-descriptions-item><el-descriptions-item label="任务类型来源">{{metricDetail.task_type_source||'—'}}</el-descriptions-item><el-descriptions-item label="数据指纹"><code>{{metricDetail.source_fingerprint||'—'}}</code></el-descriptions-item></el-descriptions><el-divider content-position="left">原理图合理性指标</el-divider><section class="rationality" :class="`is-${rationality.status||'unknown'}`"><div class="rationality-head"><div><b>{{rationalityStatus(rationality.status)}}</b><small v-if="rationality.source_uuid">记录 {{rationality.source_uuid}}</small></div><el-tag :type="rationality.status==='completed'?'success':rationality.status==='not_found'?'info':'warning'">{{rationality.quality_level||'—'}}</el-tag></div><template v-if="rationality.status==='completed'"><div class="metric-grid rationality-grid"><article v-for="item in rationalityCards" :key="item.key"><span>{{item.label}}</span><b>{{item.value}}</b><small v-if="item.help">{{item.help}}</small></article></div><el-alert v-if="rationality.judge_status==='unavailable'" :closable="false" type="warning" :title="rationality.summary"/><el-alert v-if="rationality.metrics?.source_possibly_truncated" :closable="false" type="warning" title="原始报告疑似在 65,536 字处截断；仅展示已读取图页的局部指标，不代表全工程总分。"/><el-alert v-else-if="rationality.check_type==='hscope_diagram_lint'&&!rationality.metrics?.extraction_complete" :closable="false" type="warning" title="resultText 没有完整提取预期的检查指标，请检查原始字段结构。"/><p v-if="rationality.summary&&rationality.judge_status!=='unavailable'" class="rationality-summary">{{rationality.summary}}</p><ul v-if="rationality.issues?.length" class="issue-list"><li v-for="(issue,index) in rationality.issues" :key="index"><el-tag size="small" :type="issue.severity==='high'?'danger':issue.severity==='medium'?'warning':'info'">{{issue.severity||'info'}}</el-tag><b>{{issue.category||'问题'}}</b><span>{{issue.message}}</span></li></ul></template><el-alert v-else :closable="false" :type="rationality.status==='judge_unavailable'?'warning':'info'" :title="rationalityMessage(rationality)"/><el-descriptions v-if="rationality.source_record_id" :column="2" border class="source-meta"><el-descriptions-item label="匹配方式">{{matchType(rationality.matched_by)}}</el-descriptions-item><el-descriptions-item label="记录时间">{{formatTime(rationality.source_create_time)}}</el-descriptions-item><el-descriptions-item label="检查类型">{{rationality.check_type||'—'}}</el-descriptions-item><el-descriptions-item label="记录数量">{{number(rationality.record_count)}}</el-descriptions-item></el-descriptions><details v-if="rationality.result_text"><summary>查看原始 resultText</summary><pre>{{formatResultText(rationality.result_text)}}</pre></details></section><details><summary>查看完整指标 JSON</summary><pre>{{JSON.stringify(metricDetail,null,2)}}</pre></details></template>
      <el-empty v-else-if="!detailLoading" description="该会话尚未计算指标"><el-button type="primary" :loading="calculatingSession===detailSession?.root_session_id" @click="calculateRows([detailSession])">开始计算指标</el-button></el-empty>
    </div><template #footer><el-button @click="detailVisible=false">关闭</el-button><el-button v-if="metricDetail" :loading="processLoading===detailSession?.root_session_id" @click="showProcess(detailSession)">查看计算过程</el-button><el-button v-if="metricDetail" type="primary" :loading="calculatingSession===detailSession?.root_session_id" @click="calculateRows([detailSession])">重新计算</el-button></template></el-dialog>
  </div>
</template>

<script setup>
import {computed,nextTick,onBeforeUnmount,onMounted,ref} from 'vue'
import {ElMessage} from 'element-plus'
import {createMetricJob,fetchMetricDetail,fetchMetricHealth,fetchMetricJob,fetchMetricProcess,fetchMetricSessions} from '../api'
defineOptions({name:'HistoricalMetrics'})
const now=Date.now(),timePreset=ref('1d'),customTimeRange=ref([new Date(now-24*60*60*1000),new Date(now)]),searchedWindow=ref(null),hasSearched=ref(false),endUser=ref(''),sessionId=ref(''),metricStatusFilter=ref('all'),model=ref(''),rows=ref([]),total=ref(0),page=ref(1),pageSize=ref(20),selected=ref([]),loading=ref(false),submitting=ref(false),useJudge=ref(true),health=ref({}),job=ref(null),processJob=ref(null),processLoading=ref(''),detailVisible=ref(false),detailLoading=ref(false),detailSession=ref(null),metricDetail=ref(null),calculatingSession=ref(''),clockTick=ref(Date.now()),serverClockOffsetMs=ref(0)
let pollTimer,clockTimer
function acceptJobResponse(response,requestStartedAt){job.value=response;const serverTime=Date.parse(response?.server_time||'');if(Number.isFinite(serverTime))serverClockOffsetMs.value=Math.round(((requestStartedAt+Date.now())/2)-serverTime)}
const selectedTimeWindow=()=>{const end=new Date();if(timePreset.value==='all')return{start:new Date(0),end};if(timePreset.value==='custom'){const range=customTimeRange.value;if(!range?.[0]||!range?.[1])throw new Error('请选择完整的自定义时间范围');return{start:new Date(range[0]),end:new Date(range[1])}}const days={'1d':1,'7d':7,'30d':30}[timePreset.value]||1;return{start:new Date(end.getTime()-days*24*60*60*1000),end}}
const params=()=>({start_time:searchedWindow.value?.start.toISOString(),end_time:searchedWindow.value?.end.toISOString(),end_user:endUser.value||undefined,session_id:sessionId.value||undefined,metric_status:metricStatusFilter.value,model:model.value||undefined,limit:pageSize.value,offset:(page.value-1)*pageSize.value})
async function load(){loading.value=true;try{const data=await fetchMetricSessions(params());rows.value=data.conversations||[];total.value=data.total||0}catch(error){ElMessage.error(error.response?.data?.detail||error.message)}finally{loading.value=false}}
async function search(){try{searchedWindow.value=selectedTimeWindow()}catch(error){return ElMessage.warning(error.message)}hasSearched.value=true;page.value=1;selected.value=[];await load()} async function changeSize(){page.value=1;await load()}
async function calculateSelected(){await calculateRows(selected.value)}
async function calculateRows(items){const valid=(items||[]).filter(Boolean);if(!valid.length)return;const window=searchedWindow.value||selectedTimeWindow();submitting.value=true;if(valid.length===1)calculatingSession.value=valid[0].root_session_id;try{processJob.value=null;const requestStartedAt=Date.now();acceptJobResponse(await createMetricJob({session_ids:valid.map(row=>row.root_session_id),start_time:window.start.toISOString(),end_time:window.end.toISOString(),use_llm_judge:useJudge.value}),requestStartedAt);ElMessage.success('指标计算任务已开始');poll()}catch(error){ElMessage.error(error.response?.data?.detail||error.message);calculatingSession.value=''}finally{submitting.value=false}}
async function poll(){clearTimeout(pollTimer);if(!job.value)return;try{const requestStartedAt=Date.now();acceptJobResponse(await fetchMetricJob(job.value.job_id),requestStartedAt)}catch{}if(['queued','running'].includes(job.value?.status))pollTimer=setTimeout(poll,1500);else{calculatingSession.value='';await load();if(detailVisible.value&&detailSession.value)await loadMetricDetail(detailSession.value)}}
async function openMetrics(row){detailSession.value=row;detailVisible.value=true;await loadMetricDetail(row)}
async function loadMetricDetail(row){detailLoading.value=true;metricDetail.value=null;try{metricDetail.value=await fetchMetricDetail(row.root_session_id)}catch(error){if(error.response?.status!==404)ElMessage.error(error.response?.data?.detail||error.message)}finally{detailLoading.value=false}}
async function showProcess(row){if(!row?.root_session_id)return;processLoading.value=row.root_session_id;try{const saved=await fetchMetricProcess(row.root_session_id);processJob.value={...saved,session_ids:[saved.session_id],total:1,completed:saved.status==='completed'?1:0,failed:saved.status==='failed'?1:0,phase:'completed',progress:100};detailVisible.value=false;await nextTick();document.getElementById('metric-process-panel')?.scrollIntoView({behavior:'smooth',block:'start'})}catch(error){ElMessage.warning(error.response?.data?.detail||error.message)}finally{processLoading.value=''}}
const visibleJob=computed(()=>processJob.value||job.value)
const jobProgress=computed(()=>Number(job.value?.progress??(job.value?.total?Math.round(((job.value.completed||0)+(job.value.failed||0))/job.value.total*100):0)))
const pipelineDefinitions=[
  {key:'load',label:'读取会话',description:'从 LiteLLM PostgreSQL 读取完整会话、模型、Agent、Token 与时间信息',stages:['loading_session','session_loaded']},
  {key:'rules',label:'规则指标',description:'确定性计算工具、脚本、Skill 步骤、错误与重试指标',stages:['rule_metrics']},
  {key:'classification',label:'任务分类',description:'Judge LLM 根据第一条用户 Prompt 判断任务类型',stages:['task_classification_started','task_classification_completed','task_classification_unavailable']},
  {key:'mongoQuery',label:'查询原始指标',description:'调用 Java GET 接口查询 MongoDB 中同 Session ID 的 resultText',stages:['schematic_rationality_loading','schematic_data_query_succeeded','schematic_data_query_failed']},
  {key:'rationality',label:'质量指标分析',description:'按 checkType 提取数值，并由 Judge 生成中文结论与问题',stages:['schematic_rationality_not_found','schematic_rationality_judge','schematic_rationality_completed','schematic_rationality_judge_unavailable','schematic_rationality_rules_completed']},
  {key:'judge',label:'会话 Judge',description:'与任务分类并行分析 Skill 步骤、错误、重试与疑似伪造输出',stages:['llm_judge_chunk_started','llm_judge_chunk_completed','llm_judge_completed','llm_judge_unavailable','llm_judge_skipped']},
  {key:'persist',label:'保存最终指标',description:'调用 Java POST 接口写入 HDschematicRationalityCollection',stages:['saving_metrics','schematic_data_insert_succeeded','schematic_data_insert_failed']},
]
const terminalStepStatus=(definition,events)=>{if(!events.length)return'pending';const stages=new Set(events.map(item=>item.stage));if([...stages].some(stage=>stage.endsWith('_failed')))return'failed';if(stages.has('task_classification_unavailable')||stages.has('llm_judge_unavailable')||stages.has('schematic_rationality_judge_unavailable'))return'warning';if(stages.has('llm_judge_skipped')||stages.has('schematic_rationality_not_found'))return'skipped';const successStages={load:'session_loaded',rules:'rule_metrics',classification:'task_classification_completed',judge:'llm_judge_completed',mongoQuery:'schematic_data_query_succeeded',rationality:'schematic_rationality_completed',persist:'schematic_data_insert_succeeded'};if(stages.has(successStages[definition.key])||definition.key==='rationality'&&stages.has('schematic_rationality_rules_completed'))return'success';return'running'}
const judgeStageTimes={
  classification:{start:'task_classification_started',end:['task_classification_completed','task_classification_unavailable']},
  rationality:{start:'schematic_rationality_judge',end:['schematic_rationality_completed','schematic_rationality_judge_unavailable']},
  judge:{start:'llm_judge_chunk_started',end:['llm_judge_completed','llm_judge_unavailable']},
}
function formatElapsed(milliseconds){
  const seconds=Math.floor(Math.max(0,milliseconds)/1000)
  const hours=Math.floor(seconds/3600),minutes=Math.floor(seconds%3600/60),remaining=seconds%60
  return `${hours?`${String(hours).padStart(2,'0')}:`:''}${String(minutes).padStart(2,'0')}:${String(remaining).padStart(2,'0')}`
}
function judgeTiming(definition,stepEvents,sessionEvents){
  const stages=judgeStageTimes[definition.key]
  if(!stages)return null
  const started=stepEvents.find(event=>event.stage===stages.start)
  const startMs=Date.parse(started?.timestamp||'')
  if(!Number.isFinite(startMs))return null
  const completed=stepEvents.find(event=>stages.end.includes(event.stage))
  const sessionEnded=sessionEvents.find(event=>['session_completed','session_failed'].includes(event.stage))
  const jobEnded=!['queued','running'].includes(visibleJob.value?.status)?visibleJob.value?.finished_at:null
  const endMs=Date.parse(completed?.timestamp||sessionEnded?.timestamp||jobEnded||'')
  const running=!Number.isFinite(endMs)
  const nowMs=clockTick.value-serverClockOffsetMs.value
  return {running,label:running?'Judge LLM 调用中 · 已耗时':'Judge LLM 调用耗时',duration:formatElapsed((running?nowMs:endMs)-startMs)}
}
const sessionPipelines=computed(()=>{const allEvents=visibleJob.value?.events||[];return(visibleJob.value?.session_ids||[]).map(sessionId=>{const events=allEvents.filter(event=>event.session_id===sessionId);const steps=pipelineDefinitions.map(definition=>{const stepEvents=events.filter(event=>definition.stages.includes(event.stage));return{...definition,events:stepEvents,latest:stepEvents.at(-1),status:terminalStepStatus(definition,stepEvents),judgeTiming:judgeTiming(definition,stepEvents,events)}});return{sessionId,steps,status:events.some(event=>event.stage==='session_failed')?'failed':events.some(event=>event.stage==='session_completed')?'success':events.length?'running':'pending'}})})
const eventPayload=event=>({sequence:event.sequence,stage:event.stage,outcome:event.outcome,message:event.message,timestamp:event.timestamp,input:event.input,output:event.output,interface:event.interface,detail:event.detail,chunk:event.chunk_total?`${event.chunk_index}/${event.chunk_total}`:undefined})
const compactFacts=items=>items.filter(item=>item.value!==undefined&&item.value!==null&&item.value!=='')
const stepFacts=step=>{const latest=step.latest||{},output=latest.output||{},iface=latest.interface||{},started=step.events[0]||{},input=started.input||{},calls=iface.calls||[],lastCall=calls.at?.(-1)||calls[calls.length-1]||{};if(step.key==='load')return compactFacts([{label:'读取状态',value:latest.outcome},{label:'会话',value:output.root_session_id||input.root_session_id},{label:'交互数量',value:output.interaction_count},{label:'Agent / 模型',value:[output.agent,...(output.models||[])].filter(Boolean).join(' / ')},{label:'Token',value:output.total_tokens}]);if(step.key==='rules')return compactFacts([{label:'规则分类',value:taskType(output.task_type)},{label:'指标结果',value:output.metrics},{label:'Skill 步骤',value:output.skill_steps},{label:'证据覆盖率',value:output.evidence_coverage}]);if(step.key==='classification')return compactFacts([{label:'第一条用户 Prompt',value:input.first_user_prompt||output.first_user_prompt_preview||'未从会话请求体中找到用户 Prompt'},{label:'Judge 状态',value:output.status||latest.outcome},{label:'分类结果',value:output.task_type?taskType(output.task_type):undefined},{label:'Judge 模型',value:output.model},{label:'分类理由',value:output.reason},{label:'失败原因',value:output.error||latest.detail}]);if(step.key==='judge')return compactFacts([{label:'Judge 状态',value:output.status||latest.outcome},{label:'Judge 模型',value:output.models},{label:'分片进度',value:output.chunks_total!=null?`${output.chunks_completed||0} / ${output.chunks_total}`:undefined},{label:'Token 使用',value:output.usage},{label:'Skill 事件',value:output.skill_step_events},{label:'错误 / 重试',value:{errors:output.error_events||[],retries:output.retry_events||[]}},{label:'疑似伪造输出',value:output.suspected_fabrications},{label:'失败原因',value:output.error||latest.detail}]);if(step.key==='mongoQuery')return compactFacts([{label:'接口调用状态',value:iface.status||latest.outcome},{label:'GET 接口',value:iface.endpoint},{label:'查询 Session ID',value:iface.session_ids||input.session_ids},{label:'HTTP 状态',value:lastCall.http_status},{label:'缓存',value:lastCall.cache},{label:'接口返回 Session ID',value:lastCall.record_session_ids},{label:'接口返回 status',value:lastCall.record_statuses},{label:'接口返回 checkType',value:lastCall.record_check_types},{label:'命中记录数',value:output.record_count??iface.records_matched},{label:'匹配方式',value:output.matched_by||iface.matched_by},{label:'筛选诊断',value:output.selection_diagnostic},{label:'查询返回记录',value:output.selected_record||iface.selected_record},{label:'失败原因',value:iface.error||latest.detail}]);if(step.key==='rationality')return compactFacts([{label:'分析状态',value:output.status||latest.outcome},{label:'处理结论',value:output.reason||output.summary||latest.message},{label:'筛选诊断',value:output.selection_diagnostic||output.query_diagnostic},{label:'checkType',value:output.check_type},{label:'提取指标',value:output.metrics},{label:'问题',value:output.issues},{label:'失败原因',value:output.error||latest.detail}]);if(step.key==='persist'){const saving=step.events.find(event=>event.stage==='saving_metrics')||{};const writeInput=saving.input||{};return compactFacts([{label:'接口调用状态',value:iface.status||latest.outcome},{label:'写入接口',value:iface.endpoint||saving.interface?.endpoint},{label:'HTTP 状态',value:lastCall.http_status},{label:'写入集合',value:writeInput.collectionName||iface.collection},{label:'实际写入内容',value:output.saved_record||writeInput.record},{label:'Java 接口返回',value:output.insert_response||iface.response},{label:'MongoDB 写后回读验证',value:output.read_back_verification||iface.read_back_verification},{label:'失败原因',value:iface.error||latest.detail}])}return[]}
const formatStepValue=value=>typeof value==='string'?value:JSON.stringify(value,null,2)
const stepStatus=value=>({pending:'待执行',running:'执行中',success:'已成功',warning:'部分成功',failed:'失败',skipped:'已跳过'}[value]||value),stepTag=value=>({success:'success',warning:'warning',failed:'danger',running:'warning',skipped:'info',pending:'info'}[value]||'info'),pipelineStatus=value=>({success:'计算完成',failed:'计算失败',running:'计算中',pending:'等待执行'}[value]||value),pipelineTag=value=>({success:'success',failed:'danger',running:'warning',pending:'info'}[value]||'info')
const metricCards=computed(()=>{const m=metricDetail.value?.metrics||{};return[{key:'tool',label:'工具调用成功率',value:percent(m.tool_success_rate),help:`成功 ${number(m.tool_success_count)} / 共 ${number(m.tool_call_count)}`},{key:'skill',label:'Skill 轨迹完成度',value:percent(m.skill_completeness),help:`完成 ${number(m.skill_completed_steps)} / ${number(m.skill_required_steps)} 步`},{key:'errors',label:'任务报错次数',value:number(m.error_count),help:`未恢复 ${number(m.unrecovered_error_count)}`},{key:'retries',label:'任务重试次数',value:number(m.retry_attempt_count),help:`成功恢复 ${number(m.recovered_error_count)}`},{key:'fabrication',label:'疑似伪造输出',value:number(m.suspected_fabrication_count),help:m.confirmed_fabrication_count==null?'未做确认性判定':`确认 ${number(m.confirmed_fabrication_count)}`},{key:'script',label:'脚本调用成功率',value:percent(m.script_success_rate),help:`成功 ${number(m.script_success_count)} / 共 ${number(m.script_call_count)}`} ]})
const rationality=computed(()=>metricDetail.value?.schematic_rationality||{status:'not_found'})
const qualitySummary=computed(()=>metricDetail.value?.quality_summary||metricDetail.value?.agentEvalMetrics||null)
const qualityMetricCards=computed(()=>{const summary=qualitySummary.value?.by_check_type||{};const definitions=[['hscope_diagram_lint','总检查通过率'],['hscope_block_corpus_check','语料覆盖率'],['signal-interface-checker','信号接口检查通过率'],['tianshu-drc-review','DRC审查通过率']];const cards=[];for(const [type,label] of definitions){const group=summary[type]||{};cards.push({key:`${type}.${label}`,label,value:group.rates?.[label],source:group.label||type,recordCount:group.record_count||0});if(type==='hscope_diagram_lint')for(const [name,value] of Object.entries(group.rates||{})){if(name===label)continue;cards.push({key:`${type}.${name}`,label:name,value,source:group.label||type,recordCount:group.record_count||0})}}return cards})
const formatQualityRate=value=>value==null?'—':typeof value==='string'&&value.endsWith('%')?value:percent(value)
const qualityListText=rates=>[['总检查','总检查通过率'],['语料','语料覆盖率'],['接口','信号接口检查通过率'],['DRC','DRC审查通过率']].filter(([,key])=>rates[key]!=null).map(([label,key])=>`${label} ${formatQualityRate(rates[key])}`).join(' · ')||'—'
const rationalityCards=computed(()=>{
  const m=rationality.value.metrics||{},type=String(rationality.value.check_type||'').trim()
  if(type==='hscope_diagram_lint')return [
    ...(m.overall_success_rate!=null?[{key:'overall',label:'总成功率',value:percent(m.overall_success_rate)}]:[]),
    {key:'pages',label:'已读取图页',value:number(m.pages_observed)},
    {key:'complete',label:'六项完整图页',value:number(m.pages_with_all_checks)},
    ...(m.source_possibly_truncated?[{key:'truncated',label:'源报告完整性',value:'疑似截断'}]:[]),
    ...(m.dimension_success_rates||[]).map((item,index)=>({key:item.key||`dimension-${index}`,label:item.label||`指标 ${index+1}`,value:percent(item.success_rate),help:item.total!=null?`通过 ${item.passed} / ${item.total}；覆盖 ${item.pages} 页`:undefined})),
